const PRENATAL_TITLE="產前朔望與出生前日月食的度數";const PRENATAL_DEGREE_STATE_ZH=Object.freeze({conjunction_degree:"朔：太陽和月亮同一個度數",selected:"取在地平線上方的",near_horizon_not_selected:"有一個貼近地平線，不選，兩個度數都列",both_above_horizon_not_selected:"兩個都在地平線上方，不選，兩個度數都列",both_below_horizon_not_selected:"兩個都在地平線下方，不選，兩個度數都列",not_applicable_no_horizon:"這個計算中心沒有地平線，不選，兩個度數都列",});const PRENATAL_SECT_STATE_ZH=Object.freeze({selected:"selected",sect_near_horizon_not_selected:"出生時太陽貼近地平線，日生盤或夜生盤不定，這個挑法不選，兩次都列出。",sect_unavailable_not_selected:"沒有出生時刻（或這個計算中心沒有地平線），分不出日生盤或夜生盤，這個挑法不選，兩次都列出。",});const PRENATAL_LUMINARY_ZH=Object.freeze({sun:"太陽",moon:"月亮",both:"太陽與月亮"});const PRENATAL_UMBRAL_ZH=Object.freeze({same_eclipse_as_previous_lunar:"與上一列是同一次",earlier_than_previous_lunar:"比上一列更早",});const PRENATAL_SOURCES=sourceBlocks([[null,"出處：Ptolemy《占星四書》卷三第 2 章（Robbins 英譯，Loeb 1940，頁 229–235，朔望這一句在頁 231–233；Hübner 校勘本（學者比對多份古抄本後整理出的版本）III.3）："+"取出生前最近一次朔望的度數；朔取兩個發光體共同的度數，望取在地平線上方的那一個；"+"再找在出生時主宰這個度數的行星，以它所在的度數定為上升度數。","translation_read","（Robbins 英譯）"],[null,"出處：Robbins 英譯本卷三第 2 章註 9：正文依兩個最重要的手抄本與佚名註釋者，看朔望那一刻誰在地平線上方；"+"另一個讀法看出生那一刻。本站採用前者，後者只當資訊列出。","translation_read","（Robbins 英譯與註）"],[null,"出處：Ptolemy《占星四書》卷三第 10 章（Robbins 英譯頁 277–279；Hübner III.11）：定壽命主宰（hyleg）時，"+"日生盤的候選包括前一次朔，夜生盤包括前一次望；書中沒有明說較近的另一種要不要越過。","translation_read","（Robbins 英譯）"],[null,"出處：Lilly《Christian Astrology》（1647）卷三第 104 章，頁 527–529：日生盤取前一次朔、夜生盤取前一次望，"+"較近的是另一種也要越過。","original_language_read","（為方法頁讀過，這一條沒有重讀）"],[null,"出處：Valens《占星選集》（Anthologiae）卷三第 10、12 章（Riley 英譯的重排本）：用前一次朔或望的度數推算壽命的起點。"+"書中其他幾章也用朔或望：用朔或望的主星判斷死因，用望落在陽性或陰性星座判斷父母誰先過世，"+"也用它定月份與關鍵年（卷二第 22、27、33、41 章，卷四第 2、28 章，卷五第 2、6 章）。"+"這些章號照 Kroll 校勘本與 Riley；Pingree 校勘本的卷三第 10、12 章是第 7、9 章，"+"卷二第 22、27、33 章是第 23、28、34 章，卷五第 6 章是第 4 章。","translation_read","（Riley 英譯）"],[null,"出處：Ptolemy《占星四書》卷二第 4、5、6、8 章（Robbins 英譯）：日月食主要用在世運（地區、城市與時局）；"+"第 4 章說，這類普遍事件「第一個、也最有力的原因」是日月在食時的會合；"+"第 8 章說，（出生以後發生的）日月食的度數或其對沖度數上正好有某人本命的太陽或月亮時，是「最危險、最難避開」的位置；"+"影響多久看遮蔽持續幾小時，日食一小時算一年，月食一小時算一個月。","translation_read","（Robbins 英譯）"],[null,"出處：把出生前最後一次日月食當作命盤要點的二十世紀做法：Jansky《Interpreting the Eclipses》（Para Research 1977）、"+"Lineman《Eclipses》（AFA 1984）與《Your Prenatal Eclipse》（AFA 1992）、Brady《The Eagle and the Lark》（Weiser 1992）、"+"Graves〈Introduction to Prenatal Eclipses〉（2004 年網文）。"+"Graves 只讀到網頁摘要，其餘只讀到書目或書商說明。","secondary_only"],[null,"出處：半影月食看不看得出來：Espenak〈Visual Appearance of Lunar Eclipses〉（eclipsewise.com）。"+"日月食時刻與類型以 NASA 的日月食表驗證：Eclipse Predictions by Fred Espenak and Jean Meeus (NASA's GSFC)。","original_language_read"],]);function beforeBirthText(hours){if(typeof hours!=="number"||!Number.isFinite(hours))return DASH;if(hours<1)return`出生前 ${Math.round(hours*60)} 分鐘`;if(hours<48)return`出生前 ${num(hours,1)} 小時`;return`出生前 ${num(hours/24,1)} 天`;}
