const fullMoons=events.map((event,index)=>[event.in("degree_selection").in("horizon_at_syzygy",true),rows[index][0]]).filter(([horizon])=>horizon);if(fullMoons.length){const agrees=(horizon)=>horizon.in("ecliptic_hemisphere_check")("agrees_with_altitude","boolean");tables.push({title:"望的那一刻，從出生地看太陽和月亮的高度",columns:["朔望","太陽","月亮","用黃道半球交叉檢查"],rows:fullMoons.map(([horizon,label])=>[label,altitudeText(horizon.in("sun")),altitudeText(horizon.in("moon")),agrees(horizon)?"一致":"不一致（以高度為準）",]),});if(fullMoons.some(([horizon])=>!agrees(horizon))){notes.push("交叉檢查：用黃道半球判斷（看度數落在下降點經天頂到上升點的那一半），結果和用高度判斷不同。"+"黃道貼近地平線、或月亮偏離黃道較多時會這樣；我們以高度判斷為準。");}}
